mapper.select:
SELECT c.name, COALESCE(SUM(b.amount), 0) AS value
FROM category c
LEFT JOIN bill b ON c.id = b.category_id
    AND b.user_id = #{userId}
    AND b.date >= #{start}
    AND b.date <= #{end}
WHERE c.type = #{type}
GROUP BY c.id, c.name
ORDER BY value DESC

SELECT DATE_FORMAT(date, '%m') AS month, COALESCE(SUM(amount), 0) AS amount
FROM bill
WHERE user_id = #{userId}
    AND type = #{type}
    AND YEAR(date) = #{year}
GROUP BY DATE_FORMAT(date, '%m')
ORDER BY month
